def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.append((r, c, dr, dc, color))
    # The rays appear only when multiple diagonal pairs form the motif.
    if len(pairs) < 2:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r, c, dr, dc, color in pairs:
        for sign in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] in (bg, color):
                if grid[rr][cc] == bg:
                    out[rr][cc] = color
                rr += sign * dr
                cc += sign * dc
    return out
